describe('Skip Navigation Links - First Focusable Element', () => {
  beforeEach(() => {
    cy.visit('/page');
  });

  it('should focus on skip navigation link when page loads', () => {
    // Verify skip link exists and is visible
    cy.get('[data-testid="skip-nav-link"]').should('be.visible');
    cy.get('[data-testid="skip-nav-link"]').should('contain', 'Skip to main content');

    // Verify skip link is the first focusable element
    cy.get('[data-testid="skip-nav-link"]').focus();
    cy.get('[data-testid="skip-nav-link"]').should('have.focus');

    // Verify no other elements are focusable before skip link
    cy.get('[data-testid="main-nav-item"]').should('not.have.focus');
    cy.get('[data-testid="search-input"]').should('not.have.focus');

    // Verify skip link has correct tabindex
    cy.get('[data-testid="skip-nav-link"]').should('have.attr', 'tabindex', '0');
  });

  it('should not focus on skip navigation link when it is hidden or disabled', () => {
    // Intercept page load to simulate skip link being hidden
    cy.intercept('GET', '/page').as('pageLoad');
    cy.wait('@pageLoad');

    // Verify skip link is not visible
    cy.get('[data-testid="skip-nav-link"]').should('not.exist');

    // Verify main navigation is the first focusable element
    cy.get('[data-testid="main-nav-item"]').focus();
    cy.get('[data-testid="main-nav-item"]').should('have.focus');

    // Verify skip link does not have tabindex
    cy.get('[data-testid="skip-nav-link"]').should('not.exist');
  });
});
